function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 300) return 'grid needs 1 to 300 rows.';
  const n = grid.length;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square: every row has n cells.';
    for (const v of row) {
      if (!Number.isInteger(v) || (v !== -1 && (v < 1 || v > 1000000))) return 'Each cell is -1 or a value from 1 to 10^6.';
    }
  }
  return null;
}

