function sumRemoteness(grid) {
  const n = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const seen = grid.map(row => row.map(() => false));
  const components = [];
  let total = 0;

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === -1 || seen[i][j]) {
        continue;
      }
      let sum = 0;
      let size = 0;
      const stack = [[i, j]];
      seen[i][j] = true;
      while (stack.length > 0) {
        const [row, col] = stack.pop();
        sum += grid[row][col];
        size++;
        for (const [dr, dc] of directions) {
          const nextRow = row + dr;
          const nextCol = col + dc;
          if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
            continue;
          }
          if (grid[nextRow][nextCol] === -1 || seen[nextRow][nextCol]) {
            continue;
          }
          seen[nextRow][nextCol] = true;
          stack.push([nextRow, nextCol]);
        }
      }
      components.push([sum, size]);
      total += sum;
    }
  }

  let answer = 0;
  for (const [sum, size] of components) {
    answer += (total - sum) * size;
  }
  return answer;
}

