function sumRemoteness(grid) {
  // For every open cell, flood the cells it can reach, then add up every open cell it missed.
  const n = grid.length;
  let answer = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === -1) continue;
      const reach = new Set([i * n + j]);
      const queue = [[i, j]];
      for (let head = 0; head < queue.length; head++) {
        const [r, c] = queue[head];
        const around = [[r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]];
        for (const [x, y] of around) {
          if (x >= 0 && y >= 0 && x < n && y < n && grid[x][y] !== -1 && !reach.has(x * n + y)) {
            reach.add(x * n + y);
            queue.push([x, y]);
          }
        }
      }
      for (let x = 0; x < n; x++)
        for (let y = 0; y < n; y++)
          if (grid[x][y] !== -1 && !reach.has(x * n + y)) answer += grid[x][y];
    }
  }
  return answer;
}

