function generate(rand, size) {
  const n = size === 'large' ? 70 + Math.floor(rand() * 31) : 1 + Math.floor(rand() * 5);
  // Vary how crowded the walls are so that grids range from one big region to many tiny ones.
  const blocked = size === 'large' ? 0.3 + rand() * 0.3 : rand() * 0.7;
  const top = size === 'large' || rand() < 0.3 ? 1000000 : 9;
  const grid = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) row.push(rand() < blocked ? -1 : 1 + Math.floor(rand() * top));
    grid.push(row);
  }
  return [grid];
}
